<?php
require __DIR__.'/Profiler.php';$tests=0;
function ptest($label,$fn){global $tests;$fn();$tests++;echo 'PASS '.$label."\n";}
function pa($okay){if(!$okay)throw new RuntimeException('Profiler invariant failed');}
ptest('inactive by default',static function(){pa(!Perf1Profiler::active());pa(Perf1Profiler::enter('x','test')===null);});
ptest('nested self time and attribution',static function(){Perf1Profiler::start('unit',1);$a=Perf1Profiler::enter('outer','test');$b=Perf1Profiler::enter('inner','test');$method=new ReflectionMethod(Perf1Profiler::class,'sql');$method->invoke(null,'SELECT * FROM wp_table WHERE id=1',1000,'test');Perf1Profiler::leave($b);Perf1Profiler::leave($a);$r=Perf1Profiler::finish();pa($r['calls']['outer@test']['db_statements']===1&&$r['calls']['inner@test']['db_statements']===1);pa($r['calls']['outer@test']['self_db_ns']===0&&$r['calls']['inner@test']['self_db_ns']===1000);pa(!$r['trace_truncated']&&!Perf1Profiler::active());});
ptest('normalized fingerprints contain no literals',static function(){Perf1Profiler::start('unit',1);$m=new ReflectionMethod(Perf1Profiler::class,'sql');$m->invoke(null,"SELECT * FROM wp_table WHERE email='alpha@example.invalid' AND id=123",1000,'test');$m->invoke(null,"SELECT * FROM wp_table WHERE email='beta@example.invalid' AND id=999",1000,'test');$r=Perf1Profiler::finish();pa(count($r['queries'])===1&&$r['queries'][0]['count']===2);$s=json_encode($r);pa(strpos($s,'alpha')===false&&strpos($s,'beta')===false&&strpos($s,'@example')===false);});
ptest('transaction/write boundaries distinguish repetitions',static function(){Perf1Profiler::start('unit',1);$m=new ReflectionMethod(Perf1Profiler::class,'sql');foreach(array('START TRANSACTION','SELECT * FROM wp_table WHERE id=1','SELECT * FROM wp_table WHERE id=1','UPDATE wp_table SET revision=2 WHERE id=1','SELECT * FROM wp_table WHERE id=1','COMMIT','SELECT * FROM wp_table WHERE id=1') as $sql)$m->invoke(null,$sql,1000,'test');$r=Perf1Profiler::finish();pa($r['transactions']===1&&$r['db_statements']===7);pa(array_sum(array_column($r['queries'],'same_context_repeats'))===1);pa(array_sum(array_column($r['queries'],'post_write_or_tx_repeats'))===2);});
ptest('object and immutable input contexts export counts only',static function(){Perf1Profiler::start('unit',1);$o=new stdClass();foreach(array(1,2) as $n){$t=Perf1Profiler::enter('repo::compiled','test',array('private_identifier'=>'value-not-for-export'),$o);Perf1Profiler::leave($t);}$r=Perf1Profiler::finish();$v=$r['calls']['repo::compiled@test'];pa($v['distinct_objects']===1&&$v['distinct_input_contexts']===1&&$v['object_call_histogram']===array(2));pa(strpos(json_encode($r),'value-not-for-export')===false);});
